import * as React from 'react';
import * as DiamondGridPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface DiamondGridProps extends React.ComponentPropsWithoutRef<typeof DiamondGridPrimitive.DiamondGrid> {
  className?: string;
}

export const DiamondGrid = React.forwardRef<HTMLDivElement, DiamondGridProps>(
  ({ className, children, ...props }, ref) => (
    <DiamondGridPrimitive.DiamondGrid
      ref={ref}
      className={clsx(
        'flex items-center justify-center w-full max-w-6xl mx-auto py-12 overflow-hidden',
        className
      )}
      {...props}
    >
      {children}
    </DiamondGridPrimitive.DiamondGrid>
  )
);
DiamondGrid.displayName = 'DiamondGrid';

